import requests, random, json, time, sys
url='http://154.57.164.68:39399/control'

def try_one():
    corrections=[[random.uniform(-50,50) for _ in range(4)] for _ in range(100)]
    try:
        resp=requests.post(url,json={"corrections":corrections},timeout=20)
    except Exception as e:
        return None
    if resp.status_code!=200:
        return None
    data=resp.json()
    return data

for i in range(20):
    data=try_one()
    if data is None:
        continue
    if data.get('success'):
        print('SUCCESS FOUND', data)
        break
    else:
        print(i, 'peak', data['info']['peak_temp'])

